import { createAppRscRequestHandler } from "./app-rsc-handler.js";
//#region src/server/app-rsc-combined-handler.ts
/** Combined request/response handler used by default single-stage App entries. */
function createAppRscHandler(options) {
	const appRscHandler = createAppRscRequestHandler(options);
	return Object.assign(appRscHandler, { handleResponseStage(request, ctx, props, stageOptions) {
		return import("./app-rsc-response-stage.js").then(({ renderAppWorkerResponseStage }) => renderAppWorkerResponseStage(options, request, ctx, props, stageOptions));
	} });
}
//#endregion
export { createAppRscHandler };
